import numpy as np

from photonpairlab.spdc.analysis.hom_math import hom_dip_vs_delay, polarization_overlap
from photonpairlab.spdc.simulation.results import SPDCResults
from photonpairlab.spdc.analysis.two_mode_hom_results import TwoModeHOMResults


class HOMAnalyzer:
    def __init__(self, *results: SPDCResults):
        """
        Initializes the HOMAnalyzer class.

        Args:
            *results: One or more results dictionaries generated by simulation.py.
        """
        self.results_list = list(results)

    def get_reduced_density_matrix(self, mode="signal", results_index=0):
        """
        Computes the reduced density matrix from the Joint Spectral Amplitude (JSA) data.

        Args:
            mode (str): The mode to compute ("signal" or "idler").
            results_index (int): The index of the results object to use.

        Returns:
            tuple: The reduced density matrix and the interpolated JSA.
        """
        if results_index >= len(self.results_list):
            raise IndexError(f"Invalid results_index: {results_index}. Only {len(self.results_list)} results available.")

        results = self.results_list[results_index]
        JSA = results.JSA
        # JSA has shape (N_idler, N_signal): axis 0 is idler, axis 1 is signal.
        # Tracing out idler (summing over axis 0) leaves the signal's reduced density matrix.
        if mode == "signal":
            rho = JSA.T @ JSA.conj()
        elif mode == "idler":
            rho = JSA @ JSA.T.conj()
        else:
            raise ValueError(f"Invalid mode: {mode}. Choose 'signal' or 'idler'.")

        rho /= np.trace(rho)  # Normalize trace to 1
        return rho, JSA
    
    def compute_two_mode_HOM(self, mode1="signal", mode2="signal", taus_s=None, R=0.5, T=0.5, pol1=None, pol2=None):
        """
        Computes the HOM coincidence probability vs delay for photon 1 (results[0], mode1) and
        photon 2 (results[1], mode2):

            Pc(tau) = R^2 + T^2 - 2RT * |<p1|p2>|^2 * Re Tr[rho1 rho2(tau)]

        Args:
            mode1, mode2 (str): "signal" or "idler" for each photon.
            taus_s (np.ndarray, optional): Delays in seconds.
            R, T (float): Beam-splitter reflectivity and transmissivity.
            pol1, pol2 (array-like, optional): Jones vectors of the two photons. None (default) means
                identical polarizations, i.e. |<p1|p2>|^2 = 1. See hom_math.linear_polarization.
        """
        if len(self.results_list) < 2:
            raise ValueError("At least two results are required to compute two-mode HOM interference.")

        rho1, padded_jsa = self.get_reduced_density_matrix(mode=mode1, results_index=0)
        rho2, _         = self.get_reduced_density_matrix(mode=mode2, results_index=1)

        results1 = self.results_list[0]
        results2 = self.results_list[1]

        # Choose wavelengths according to mode, and ensure they match if you require that
        if mode1 == "signal":
            wl1 = np.array(results1.SignalWavelengths)
        else:
            wl1 = np.array(results1.IdlerWavelengths)

        if mode2 == "signal":
            wl2 = np.array(results2.SignalWavelengths)
        else:
            wl2 = np.array(results2.IdlerWavelengths)

        # If you truly require same grid, enforce it:
        if wl1.shape != wl2.shape or not np.allclose(wl1, wl2):
            raise ValueError("Wavelength grids do not match; resample/interpolate onto a common grid first.")

        c = results1.c  # speed of light from your results dict
        # Keep rho's row/column order: sorting would misalign the frequency bins with rho.
        freqs = c / wl1  # Hz if wl in meters
        pol_overlap = polarization_overlap(pol1, pol2)

        N = len(freqs)

        # Define delay axis if not provided:
        if taus_s is None:
            # A reasonable default delay range based on bandwidth and grid spacing:
            df = abs(freqs[-1] - freqs[0]) / (N - 1)
            # time window ~ 1/df; sample a few windows
            t_max = 5 / df
            taus_s = np.linspace(-t_max, t_max, (2*N - 1)*100)

        Pc = hom_dip_vs_delay(rho1, rho2, freqs, taus_s, R=R, T=T, pol_overlap=pol_overlap)

        # Useful metrics
        overlap0 = np.real(np.trace(rho1 @ rho2))
        purity1  = np.real(np.trace(rho1 @ rho1))
        purity2  = np.real(np.trace(rho2 @ rho2))

        results = TwoModeHOMResults(
            coincidence_probabilities=Pc,
            tau_s=taus_s,
            tau_fs=taus_s * 1e15,
            overlap_at_zero_delay=overlap0,
            purity1=purity1,
            purity2=purity2,
            polarization_overlap=pol_overlap,
        )
        return results